22	/**
23	 * 航班载重平衡舱单与复核放行接口（实现阶段补齐委托）。
24	 */
25	@RestController
26	@RequestMapping("/api/flights/{flightId}/loadsheet")
27	public class LoadsheetController {
28	
29	    private final WeightBalanceService service;
30	
31	    public LoadsheetController(WeightBalanceService service) {
32	        this.service = service;
33	    }
34	
35	    @PostMapping
36	    @ResponseStatus(HttpStatus.CREATED)
37	    public ManifestResponse create(@PathVariable Long flightId,
38	                                   @Valid @RequestBody CreateManifestRequest request) {
