39	        BigDecimal zfw = oew.add(payload);
40	        BigDecimal tow = zfw.add(fuel);
41	
42	        BigDecimal zfwMoment = oew.multiply(ac.oewArm()).add(payloadMoment);
43	        BigDecimal towMoment = zfwMoment.add(fuel.multiply(ac.fuelArm()));
44	
45	        BigDecimal cgZfw = toMacPct(ac, zfwMoment.divide(zfw, 6, RoundingMode.HALF_UP));
46	        BigDecimal cgTow = toMacPct(ac, towMoment.divide(tow, 6, RoundingMode.HALF_UP));
47	
48	        List<String> violations = new ArrayList<>();
49	        BigDecimal payloadLimit = BigDecimal.valueOf(ac.mzfwKg() - ac.oewKg());
50	        if (payload.compareTo(payloadLimit) > 0) {
51	            violations.add("总业载 " + payload + "kg 超过上限 MZFW-OEW=" + payloadLimit + "kg");
52	        }
53	        if (zfw.compareTo(BigDecimal.valueOf(ac.mzfwKg())) > 0) {
54	            violations.add("ZFW " + zfw + "kg 超过 MZFW " + ac.mzfwKg() + "kg");
55	        }
56	        if (tow.compareTo(BigDecimal.valueOf(ac.mtowKg())) > 0) {
57	            violations.add("TOW " + tow + "kg 超过 MTOW " + ac.mtowKg() + "kg");
58	        }
59	        if (fuel.compareTo(BigDecimal.ZERO) < 0) {
60	            violations.add("加油量不得为负");
61	        }
62	        List<EnvelopeChecker.EnvelopeVertex> polygon = toPolygon(ac.envelope());
63	        if (!EnvelopeChecker.contains(polygon, zfw, cgZfw)) {
64	            violations.add("无油重心 " + cgZfw + "%MAC @ " + zfw + "kg 超出包线");
65	        }
66	        if (!EnvelopeChecker.contains(polygon, tow, cgTow)) {
67	            violations.add("起飞重心 " + cgTow + "%MAC @ " + tow + "kg 超出包线");
68	        }
69	
70	        return new WeightBalanceResult(
71	                pax,
72	                payload,
73	                fuel,
74	                zfw,
75	                tow,
