        rs.getTimestamp("released_at") == null ? null : rs.getTimestamp("released_at").toLocalDateTime()
);

private static final RowMapper<UldOccupancyRow> OCCUPANCY_MAPPER = (rs, n) -> new UldOccupancyRow(
